import{_ as e,c as i,o as l,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"安裝 Persim","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1795170900000}'),r={name:"zh-TW/guide/installation.md"};function o(s,a,n,d,p,h){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="安裝-persim" tabindex="-1">安裝 Persim <a class="header-anchor" href="#安裝-persim" aria-label="Permalink to &quot;安裝 Persim&quot;">​</a></h1><p>下載、設為預設瀏覽器，再把書籤帶過來。</p><h2 id="下載與安裝" tabindex="-1">下載與安裝 <a class="header-anchor" href="#下載與安裝" aria-label="Permalink to &quot;下載與安裝&quot;">​</a></h2><ol><li>開啟 <a href="https://apps.apple.com/app/id6835099132" target="_blank" rel="noreferrer">Mac App Store</a>，搜尋 Persim。</li><li>下載完成後，把應用程式拖進「應用程式」資料夾；系統詢問時確認即可。</li><li>想設為預設瀏覽器，開啟「系統設定 → 預設網頁瀏覽器」，選擇 Persim。</li></ol><p>需要 macOS 12 及以上，Apple Silicon 和 Intel 晶片都支援。</p><h2 id="第一次開啟" tabindex="-1">第一次開啟 <a class="header-anchor" href="#第一次開啟" aria-label="Permalink to &quot;第一次開啟&quot;">​</a></h2><ul><li>在 <code>persim://settings</code> 的「一般」裡選擇外觀、主色與書籤列顯示方式。</li><li>介面語言有 25 種；切換後重新開啟視窗生效。</li><li>新分頁已經放好常用網站與 AI 直達入口，直接用即可。</li></ul><h2 id="把書籤帶過來" tabindex="-1">把書籤帶過來 <a class="header-anchor" href="#把書籤帶過來" aria-label="Permalink to &quot;把書籤帶過來&quot;">​</a></h2><ol><li>在 Chrome 或 Edge 裡把書籤匯出成 HTML 檔。</li><li>開啟 Persim 的書籤管理員，選擇「匯入 HTML」並選取檔案。</li><li>多層資料夾會還原，重複網址會自動略過；書籤列也可以隨時拖曳排序。</li></ol><h2 id="後續更新" tabindex="-1">後續更新 <a class="header-anchor" href="#後續更新" aria-label="Permalink to &quot;後續更新&quot;">​</a></h2><p>在 Mac App Store 的「更新」頁取得新版本，已有資料會保留。</p>',11)])])}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
